<?php require 'config.php';$u=require_login();require_innovations();page_start('Inbox',$u);heading('YOUR COMMUNITY HAS SOMETHING TO SAY','Stay in the loop.','Replies, project feedback, mentor updates and workshop notices—all in one place.'); ?>
<section class="card"><div class="section-title"><h2>Your notifications</h2><form method="post" action="innovate.php"><?php innovation_hidden('read_all');?><button class="ghost">Mark all read</button></form></div><p class="meta">In-app notices only. No emails or browser push. Workshop reminders are checked when you open a signed-in page within 48 hours of the event.</p>
<?php $items=rows('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']]);foreach($items as $item):?><article class="notification-item <?=$item['is_read']?'read':'unread'?>"><div><span class="badge"><?=$item['is_read']?'Read':'Unread'?></span><h3><?=e($item['message'])?></h3><small><?=e($item['created_at'])?></small><p><a href="<?=e($item['url'])?>">Open related page →</a></p></div><?php if(!$item['is_read']):?><form method="post" action="innovate.php"><?php innovation_hidden('read_notification',(int)$item['id']);?><button class="ghost">Mark read</button></form><?php endif;?></article><?php endforeach;if(!$items):?><div class="empty-state"><h2>You're all caught up.</h2><p>New notifications appear when someone replies, responds to mentorship or publishes a workshop.</p></div><?php endif;?></section>
<?php page_end(); ?>